// Browser check of the compact-copy encoder (src/lib/music/transcode.ts, ai/features/music/music.md).
// Reuses the Vite dev server when one answers at JOURNAL_URL or http://localhost:5173 (start it yourself with
// `pnpm dev --port 5173`); with no URL set and nothing answering, it starts that server for the run and stops it
// afterwards. tmp/ (the fixtures) is served from a second origin with CORS and Range support, like
// check-music-probe.mjs (generated by `python3 scripts/make-music-fixtures.py`, which needs ffmpeg).
// In Playwright's Chromium it records the format pickCopyFormat() chooses, makes copies of FLAC 16/44.1 and 24/96,
// MP3, WAV and a CUE slice of the gapless album image (plus the other inputs the module supports), and checks that
// each decodes, lasts as long as its source (±50 ms) and lands within ±25% of the target bitrate; that the copy
// lines up with the original; that hi-res input leaves no alias in the audible band; that an abort rejects
// promptly; and that WavPack is refused with the Chinese message. Prints a table and exits 1 on any failure.
// --long adds a 62-minute album image (generated once with ffmpeg into tmp/music-transcode/) and checks that the
// renderer's memory stays far below the decoded PCM size (Linux, from /proc) — the streaming guarantee.
// MUSIC_TRANSCODE_BROWSER=chrome (or msedge) runs an installed Chrome instead: on macOS or Windows that exercises
// the AAC path, which Chromium on Linux cannot (it has no AAC encoder).
// Usage: DIARY_NODE_MODULES=$(npm root -g) node scripts/check-music-transcode.mjs [--long]
import { dependency, baseUrl } from './lib/deps.mjs';
import { spawn, spawnSync } from 'node:child_process';
import { createReadStream, existsSync, mkdirSync, readdirSync, readFileSync, statSync } from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const { chromium } = dependency('playwright');
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const served = path.join(root, 'tmp');
const fixtures = path.join(served, 'music-fixtures');
const UNSUPPORTED = '这台设备没法把这种格式转成省流副本';
const LONG = process.argv.includes('--long');
const LONG_SEC = 62 * 60;
const longFile = path.join(served, 'music-transcode/album-62min.flac');

if (!existsSync(path.join(fixtures, 'manifest.json'))) {
    console.log('tmp/music-fixtures is missing; running python3 scripts/make-music-fixtures.py');
    const made = spawnSync('python3', ['scripts/make-music-fixtures.py'], { cwd: root, stdio: 'inherit' });
    if (made.status !== 0) process.exit(2);
}
const manifest = JSON.parse(readFileSync(path.join(fixtures, 'manifest.json'), 'utf8'));
const info = Object.fromEntries(manifest.files.map((f) => [f.path, f]));

// The long album image: a quiet chord with a slow swell, 16/44.1 stereo, about 40 MB of FLAC.
if (LONG && !existsSync(longFile)) {
    console.log(`Generating ${path.relative(root, longFile)} with ffmpeg`);
    mkdirSync(path.dirname(longFile), { recursive: true });
    const voice = '0.12*(sin(2*PI*220*t)+sin(2*PI*277.18*t)+sin(2*PI*329.63*t))*(0.8+0.2*sin(2*PI*0.05*t))';
    const made = spawnSync('ffmpeg', [
        ...['-hide_banner', '-loglevel', 'error', '-y', '-f', 'lavfi'],
        ...['-i', `aevalsrc='${voice}|${voice}':s=44100:d=${LONG_SEC}`, '-c:a', 'flac', '-sample_fmt', 's16', longFile]
    ]);
    if (made.status !== 0) {
        console.error(`ffmpeg failed: ${made.stderr}`);
        process.exit(2);
    }
}

// Linux only: the largest resident set, in MiB, among Chromium renderer processes (from /proc).
const rendererMiB = () => {
    if (process.platform !== 'linux') return null;
    let most = 0;
    for (const pid of readdirSync('/proc').filter((name) => /^\d+$/.test(name))) {
        try {
            if (!readFileSync(`/proc/${pid}/cmdline`, 'utf8').includes('--type=renderer')) continue;
            const kb = /VmRSS:\s+(\d+)/.exec(readFileSync(`/proc/${pid}/status`, 'utf8'));
            if (kb) most = Math.max(most, Number(kb[1]) / 1024);
        } catch {
            // the process exited while we looked
        }
    }
    return most;
};

// Range-capable static server for tmp/, with CORS so the page (on the Vite origin) can fetch the audio.
const TYPES = { '.flac': 'audio/flac', '.mp3': 'audio/mpeg', '.wav': 'audio/wav', '.ogg': 'audio/ogg' };
const server = http.createServer((req, res) => {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Headers', 'Range');
    res.setHeader('Access-Control-Expose-Headers', 'Content-Range, Accept-Ranges, Content-Length');
    if (req.method === 'OPTIONS') return res.writeHead(204).end();
    const file = path.join(served, ...new URL(req.url, 'http://localhost').pathname.split('/').map(decodeURIComponent));
    if (!file.startsWith(served) || !existsSync(file)) return res.writeHead(404).end();
    const size = statSync(file).size;
    res.setHeader('Accept-Ranges', 'bytes');
    res.setHeader('Content-Type', TYPES[path.extname(file)] ?? 'application/octet-stream');
    const range = /bytes=(\d*)-(\d*)/.exec(req.headers.range ?? '');
    if (!range) {
        res.writeHead(200, { 'Content-Length': size });
        return createReadStream(file).pipe(res);
    }
    const start = range[1] ? Number(range[1]) : Math.max(0, size - Number(range[2]));
    const end = range[1] && range[2] ? Math.min(Number(range[2]), size - 1) : size - 1;
    res.writeHead(206, { 'Content-Range': `bytes ${start}-${end}/${size}`, 'Content-Length': end - start + 1 });
    createReadStream(file, { start, end }).pipe(res);
});
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const host = `http://127.0.0.1:${server.address().port}`;
const origin = `${host}/music-fixtures`;

// The dev server: reuse one that answers, else start `pnpm dev --port 5173` for this run.
const answers = async (url) => {
    try {
        return (await fetch(url, { signal: AbortSignal.timeout(2000) })).ok;
    } catch {
        return false;
    }
};
let devServer = null;
if (!(await answers(baseUrl()))) {
    if (process.env.JOURNAL_URL) {
        console.error(`No dev server answers at ${baseUrl()}.`);
        process.exit(2);
    }
    console.log('Starting the dev server: pnpm dev --port 5173 --strictPort');
    devServer = spawn('pnpm', ['dev', '--port', '5173', '--strictPort'], {
        cwd: root,
        stdio: 'ignore',
        detached: true
    });
    const deadline = Date.now() + 60_000;
    while (!(await answers(baseUrl()))) {
        if (Date.now() > deadline || devServer.exitCode !== null) {
            console.error('The dev server did not come up.');
            if (devServer.exitCode === null) process.kill(-devServer.pid, 'SIGTERM');
            process.exit(2);
        }
        await new Promise((resolve) => setTimeout(resolve, 500));
    }
}

// Track 2 of gapless/album.cue runs from its INDEX 01 to track 3's (mm:ss:ff, frames are 1/75 s). The sheet is GBK;
// the INDEX lines are ASCII, so latin1 reads them fine.
const cue = readFileSync(path.join(fixtures, 'gapless/album.cue'), 'latin1');
const indexOf = (track) => {
    const [, mm, ss, ff] = new RegExp(`TRACK 0${track} AUDIO[\\s\\S]*?INDEX 01 (\\d+):(\\d+):(\\d+)`).exec(cue);
    return Number(mm) * 60 + Number(ss) + Number(ff) / 75;
};
const track2 = { startSec: indexOf(2), endSec: indexOf(3) };

// Copy cases: `expect` is the length of the audio the copy must hold (manifest duration or slice length).
const COPIES = [
    { name: 'FLAC 16/44.1', file: 'formats/01-flac-16-44.flac', align: true },
    { name: 'FLAC 24/96', file: 'formats/02-flac-24-96.flac', probeHz: [1000, 18000], alias: 18000 },
    {
        name: 'MP3 320',
        file: 'formats/07-mp3-320-gbk-tags.mp3',
        align: true,
        notes: 'lag = LAME delay: mediabunny keeps it, decodeAudioData trims it'
    },
    { name: 'WAV 24/48', file: 'formats/08-wav-24-48.wav' },
    { name: 'CUE track 2', file: 'gapless/album.flac', ...track2 },
    { name: 'FLAC 24/192', file: 'formats/03-flac-24-192.flac', probeHz: [1000, 12000], alias: 12000 },
    { name: 'WAV f32/48', file: 'formats/09-wav-f32-48.wav', align: true, strictAlign: true },
    {
        name: 'slice 60–75 s',
        file: 'formats/15-flac-16-44-4min.flac',
        startSec: 60,
        endSec: 75,
        align: true,
        strictAlign: true
    },
    { name: 'Ogg Opus', file: 'formats/11-opus-160.ogg', align: true },
    { name: 'WebM Opus', file: 'formats/12-opus-160.webm', align: true },
    { name: 'Ogg Vorbis', file: 'formats/13-vorbis-q6.ogg', align: true }
];
// Inputs this device must refuse with the Chinese message (`required`) or may refuse (codec missing here).
const REFUSALS = [
    { name: 'WavPack', file: 'formats/14-wavpack-16-44.wv', required: true },
    { name: 'ALAC', file: 'formats/04-alac-16-44.m4a' },
    { name: 'AAC 256 (M4A)', file: 'formats/06-aac-256.m4a' },
    { name: 'AIFF', file: 'formats/10-aiff-16-44.aiff' }
];

const rows = [];
const failures = [];
const check = (row, ok, why) => {
    if (!ok) {
        row.pass = false;
        failures.push(`${row.case}: ${why}`);
    }
};
const kbps = (bits) => (bits ? `${Math.round(bits / 1000)}` : '');

const browser = await chromium.launch({ channel: process.env.MUSIC_TRANSCODE_BROWSER || undefined });
const page = await browser.newPage();
const pageErrors = [];
page.on('pageerror', (error) => pageErrors.push(String(error)));
try {
    // A first visit may make Vite optimise mediabunny and reload the page; wait until the harness stays up.
    await page.goto(`${baseUrl()}/scripts/fixtures/music-transcode.html`);
    await page.locator('#status', { hasText: 'ready' }).waitFor({ timeout: 60_000 });
    await page.waitForLoadState('networkidle');
    await page.locator('#status', { hasText: 'ready' }).waitFor({ timeout: 60_000 });
    const call = (fn, arg) => page.evaluate(([name, value]) => window.musicTranscode[name](value), [fn, arg]);

    const format = await call('pick');
    const pickRow = {
        case: 'pickCopyFormat()',
        input: '',
        pass: true,
        result: format ? `${format.codec}/${format.container} ${kbps(format.bitrate)} kbps` : 'null'
    };
    rows.push(pickRow);
    check(pickRow, format !== null, 'no encodable format');
    if (!format) throw new Error('nothing to encode with');

    for (const c of COPIES) {
        const source = info[c.file];
        const expect = c.endSec !== undefined ? c.endSec - c.startSec : source.duration_s;
        const r = await call('copy', {
            url: `${origin}/${c.file}`,
            format,
            startSec: c.startSec,
            endSec: c.endSec,
            sourceRate: source.sample_rate,
            align: c.align,
            probeHz: c.probeHz
        });
        const row = { case: c.name, input: c.file, pass: true, result: r.ok ? 'copied' : `error: ${r.error}` };
        rows.push(row);
        check(row, r.ok, r.error);
        if (!r.ok) continue;
        const priming = format.codec === 'aac' ? 3136 / r.sampleRate : 0; // AAC: no edit list, priming + padding
        const delta = r.decoded.duration - expect;
        Object.assign(row, {
            size: `${(r.size / 1024).toFixed(0)} KiB`,
            kbps: `${kbps(r.bitrate)}/${kbps(format.bitrate)}`,
            duration: `${expect.toFixed(3)} → ${r.decoded.duration.toFixed(3)} s (${delta >= 0 ? '+' : ''}${(delta * 1000).toFixed(1)} ms)`,
            rate: `${source.sample_rate / 1000}→${r.sampleRate / 1000}k`,
            lag: r.alignment ? `${r.alignment.lagSamples} smp (r=${r.alignment.correlation})` : '',
            ms: `${r.ms} ms (${Math.round(expect / (r.ms / 1000))}× real time)`,
            notes: c.notes ?? ''
        });
        check(row, !r.decoded.error, `copy does not decode: ${r.decoded.error}`);
        check(row, r.decoded.channels === 2 && r.channels === 2, 'copy is not stereo');
        check(row, delta >= -0.05 && delta <= 0.05 + priming, `duration off by ${(delta * 1000).toFixed(1)} ms`);
        check(row, Math.abs(r.bitrate / format.bitrate - 1) <= 0.25, `bitrate ${kbps(r.bitrate)} kbps`);
        check(row, r.mime === format.mime, `blob type ${r.mime}`);
        check(row, r.progress.last === 1 && r.progress.monotonic, 'progress does not climb to 1');
        const held = r.contents;
        check(row, held.audioTracks === 1 && held.videoTracks === 0, `copy holds ${JSON.stringify(held)}`);
        check(
            row,
            held.tags.length === 0 && held.rawTags.length === 0,
            `copy carries tags ${held.tags} ${held.rawTags}`
        );
        // Opus keeps its pre-skip and must line up; an AAC copy lags by the encoder delay, which is only reported.
        if (c.strictAlign && format.codec === 'opus')
            check(
                row,
                r.alignment && Math.abs(r.alignment.lagSamples) <= 1 && r.alignment.correlation > 0.9,
                'copy does not line up with the original'
            );
        if (c.alias) {
            const builtin = await call('builtinProbe', { url: `${origin}/${c.file}`, probeHz: c.probeHz }).catch(
                () => null
            );
            const db = r.probes[c.alias];
            row.notes =
                `alias @${c.alias / 1000} kHz: ${db} dBFS` +
                (builtin ? ` (mediabunny resampler: ${builtin[c.alias]})` : '');
            check(row, db < -70, `alias at ${c.alias} Hz is ${db} dBFS`);
            check(row, r.probes[1000] > -21.5 && r.probes[1000] < -18.5, `1 kHz tone at ${r.probes[1000]} dBFS`);
        }
    }

    for (const c of REFUSALS) {
        const r = await call('copy', { url: `${origin}/${c.file}`, format });
        const refused = !r.ok && r.error === UNSUPPORTED;
        const row = {
            case: `refuse ${c.name}`,
            input: c.file,
            pass: true,
            result: r.ok ? 'copied' : `refused: ${r.error}`,
            ms: `${r.ms} ms`
        };
        rows.push(row);
        if (c.required) check(row, refused, 'not refused with the Chinese message');
        else check(row, r.ok || refused, `failed another way: ${r.error}`);
    }

    const past = await call('copy', {
        url: `${origin}/formats/01-flac-16-44.flac`,
        format,
        startSec: 100,
        endSec: 110
    });
    const pastRow = {
        case: 'slice past the end',
        input: 'formats/01-flac-16-44.flac',
        pass: true,
        result: past.ok ? 'copied' : `refused: ${past.error}`,
        notes: '100–110 s of a 20 s file'
    };
    rows.push(pastRow);
    check(pastRow, !past.ok && past.error === '这一段的起止时间不对', 'not refused as a bad range');

    const aborted = await call('abort', { url: `${origin}/formats/15-flac-16-44-4min.flac`, format, atFraction: 0.2 });
    const abortRow = {
        case: 'abort at 20%',
        input: 'formats/15-flac-16-44-4min.flac',
        pass: true,
        result: aborted.outcome === 'rejected' ? `rejected ${aborted.errorName}: ${aborted.error}` : aborted.outcome,
        ms: aborted.settleMs !== undefined ? `${aborted.settleMs} ms after abort` : ''
    };
    rows.push(abortRow);
    check(abortRow, aborted.outcome === 'rejected' && aborted.errorName === 'AbortError', `outcome ${aborted.outcome}`);
    check(abortRow, (aborted.settleMs ?? Infinity) < 2000, 'took too long to stop');

    if (LONG) {
        const before = rendererMiB();
        let peak = before;
        const poll = setInterval(() => (peak = Math.max(peak, rendererMiB())), 200);
        const r = await call('copy', { url: `${host}/music-transcode/album-62min.flac`, format, decode: false });
        clearInterval(poll);
        const pcmMiB = (LONG_SEC * 44_100 * 2 * 4) / 2 ** 20;
        const grew = before === null ? null : Math.round(peak - before);
        const longRow = {
            case: 'long: 62-min album image',
            input: 'music-transcode/album-62min.flac',
            pass: true,
            result: r.ok ? 'copied' : `error: ${r.error}`
        };
        rows.push(longRow);
        check(longRow, r.ok, r.error);
        if (r.ok) {
            Object.assign(longRow, {
                rate: `44.1→${r.sampleRate / 1000}k`,
                size: `${(r.size / 2 ** 20).toFixed(1)} MiB`,
                kbps: `${kbps(r.bitrate)}/${kbps(format.bitrate)}`,
                duration: `${LONG_SEC.toFixed(3)} → ${(r.durationMs / 1000).toFixed(3)} s (copy length)`,
                ms: `${r.ms} ms (${Math.round(LONG_SEC / (r.ms / 1000))}× real time)`,
                notes:
                    grew === null
                        ? 'memory not measured on this OS'
                        : `renderer grew ${grew} MiB at peak; decoded PCM would be ${Math.round(pcmMiB)} MiB`
            });
            check(longRow, Math.abs(r.durationMs - LONG_SEC * 1000) <= 50, `copy holds ${r.durationMs} ms`);
            check(longRow, Math.abs(r.bitrate / format.bitrate - 1) <= 0.25, `bitrate ${kbps(r.bitrate)} kbps`);
            check(longRow, grew === null || grew < pcmMiB / 2, `renderer grew ${grew} MiB`);
        }
    }

    const errorRow = {
        case: 'page errors',
        input: '',
        pass: true,
        result: pageErrors.length ? pageErrors.join('; ') : 'none'
    };
    rows.push(errorRow);
    check(errorRow, pageErrors.length === 0, 'uncaught errors in the page');
} catch (error) {
    failures.push(`run: ${error instanceof Error ? error.message : error}`);
} finally {
    await browser.close();
    server.close();
    if (devServer) process.kill(-devServer.pid, 'SIGTERM');
}

const COLUMNS = ['case', 'input', 'result', 'rate', 'size', 'kbps', 'duration', 'lag', 'ms', 'notes'];
const cells = rows.map((row) => ({ ...row, pass: undefined, case: `${row.pass ? 'PASS' : 'FAIL'} ${row.case}` }));
const widths = COLUMNS.map((k) => Math.max(k.length, ...cells.map((row) => String(row[k] ?? '').length)));
const line = (row) => COLUMNS.map((k, i) => String(row[k] ?? '').padEnd(widths[i])).join(' | ');
console.log(line(Object.fromEntries(COLUMNS.map((k) => [k, k]))));
console.log(widths.map((w) => '-'.repeat(w)).join('-|-'));
for (const row of cells) console.log(line(row));
if (failures.length) {
    console.log(`\n${failures.length} failure(s):\n- ${failures.join('\n- ')}`);
    process.exit(1);
}
console.log('\nmusic transcode check passed');
